module.exports = "<section\n  class=\"bmb_home-notification-card\"\n  [ngStyle]=\"{ '--maxHeight': maxHeight() }\"\n>\n  <bmb-home-card\n    icon=\"notifications\"\n    bgIconAppearance=\"red-primary\"\n    title=\"Mis Notificaciones\"\n    [isMobile]=\"false\"\n    (onExpandClick)=\"onExpandClick.emit()\"\n  >\n    <div class=\"bmb_home-notification-card-content\">\n      <bmb-tabs\n        [tabs]=\"tabsConfig()\"\n        [(selectedTabId)]=\"selectedTab\"\n      ></bmb-tabs>\n      @switch (selectedTab()) {\n        @case (1) {\n          <bmb-alert-center-list\n            [alerts]=\"parsedData()\"\n            [enableMultipleSelection]=\"true\"\n            [showSelectAllButton]=\"true\"\n            (alertSelected)=\"handleAlertSelected($event)\"\n          />\n        }\n        @case (2) {\n          @if (showAdvertisements()) {\n            <bmb-alert-center-ads\n              [advertisements]=\"advertisements()\"\n              (alertEvent)=\"handleAlertEvent($event)\"\n            />\n          } @else {\n            <bmb-alert-center-list\n              [alerts]=\"unreadAlerts()\"\n              [enableMultipleSelection]=\"true\"\n              [showSelectAllButton]=\"true\"\n              (alertSelected)=\"handleAlertSelected($event)\"\n            />\n          }\n        }\n        @default {\n          <div>Invalid ID selected</div>\n        }\n      }\n    </div>\n  </bmb-home-card>\n</section>\n";

